/* LGS tarzı özel denemeler — 7. sınıf müfredatına göre özgün, yeni nesil sorular */
window.LGS_OZEL = (function () {
  'use strict';
  const F = (a, b) => `<span class="frac"><span>${a}</span><span>${b}</span></span>`;
  const P = t => `<div class="paragraf">${t}</div>`;
  const tablo = (b, satir) => `<div class="tb-wrap"><table class="tb"><tr>${b.map(x => `<th>${x}</th>`).join('')}</tr>${satir.map(r => `<tr>${r.map(h => `<td>${h}</td>`).join('')}</tr>`).join('')}</table></div>`;
  const Q = (ders, konu, soru, secenekler, dogru, cozum, sekil) => ({ ders, konu, seviye: 3, soru, secenekler, dogru, cozum, sekil: sekil || '' });

  /* ---------- Çizimler ---------- */
  function sutun(veri, max, adim, birim) {
    const x0 = 46, y0 = 190, gw = 370, gh = 160, bw = gw / veri.length; let s = '<svg class="fig" viewBox="0 0 440 220">';
    for (let v = 0; v <= max; v += adim) { const y = y0 - gh * v / max; s += `<line class="${v ? 'ld' : 'l'}" x1="${x0}" y1="${y}" x2="${x0 + gw}" y2="${y}" style="${v ? 'opacity:.5' : ''}"/><text x="${x0 - 8}" y="${y + 5}" text-anchor="end" class="m">${v}</text>`; }
    veri.forEach((d, i) => { const h = gh * d[1] / max, x = x0 + i * bw + bw * 0.22; s += `<rect x="${x}" y="${y0 - h}" width="${bw * 0.56}" height="${h}" rx="4" class="fa" style="opacity:.85"/><text x="${x + bw * 0.28}" y="${y0 + 20}" text-anchor="middle" class="m">${d[0]}</text>`; });
    return s + `<line class="l" x1="${x0}" y1="${y0}" x2="${x0}" y2="${y0 - gh - 6}"/><text x="${x0 - 34}" y="14" class="m">${birim}</text></svg>`;
  }
  function pasta(dilimler) {
    const cx = 150, cy = 110, r = 90; let a0 = -90; let s = '<svg class="fig sm" viewBox="0 0 300 220" style="max-width:260px">';
    const sn = ['fI', 'fW', 'fG', 'fR', 'fa'];
    dilimler.forEach((d, i) => {
      const a1 = a0 + d[1], rad = a => a * Math.PI / 180;
      const p0 = [cx + r * Math.cos(rad(a0)), cy + r * Math.sin(rad(a0))], p1 = [cx + r * Math.cos(rad(a1)), cy + r * Math.sin(rad(a1))];
      s += `<path d="M${cx} ${cy} L${p0[0].toFixed(1)} ${p0[1].toFixed(1)} A${r} ${r} 0 ${d[1] > 180 ? 1 : 0} 1 ${p1[0].toFixed(1)} ${p1[1].toFixed(1)} Z" class="${sn[i % 5]}" style="opacity:.8;stroke:var(--card);stroke-width:2"/>`;
      const m = rad((a0 + a1) / 2);
      s += `<text x="${(cx + r * .58 * Math.cos(m)).toFixed(1)}" y="${(cy + r * .58 * Math.sin(m)).toFixed(1)}" text-anchor="middle" font-size="12">${d[0]}</text><text x="${(cx + r * .58 * Math.cos(m)).toFixed(1)}" y="${(cy + r * .58 * Math.sin(m) + 15).toFixed(1)}" text-anchor="middle" font-size="12">${d[2] || ''}</text>`;
      a0 = a1;
    });
    return s + '</svg>';
  }
  function paralel(ust, alt) {
    const yaz = ([x, y], e) => (e.UR ? `<text x="${x + 14}" y="${y - 8}" class="a">${e.UR}</text>` : '') + (e.UL ? `<text x="${x - 12}" y="${y - 8}" text-anchor="end" class="a">${e.UL}</text>` : '') + (e.LL ? `<text x="${x - 24}" y="${y + 22}" text-anchor="end" class="a">${e.LL}</text>` : '') + (e.LR ? `<text x="${x + 10}" y="${y + 22}" class="a">${e.LR}</text>` : '');
    return `<svg class="fig" viewBox="0 0 440 230"><line class="l" x1="30" y1="70" x2="400" y2="70"/><line class="l" x1="30" y1="150" x2="400" y2="150"/><line class="l" x1="130" y1="210" x2="250" y2="10"/><text x="410" y="75">d₁</text><text x="410" y="155">d₂</text><text x="256" y="18">k</text>${yaz([214, 70], ust)}${yaz([166, 150], alt)}<text x="30" y="222" class="m">d₁ ∥ d₂ · Şekil ölçekli değildir.</text></svg>`;
  }
  function kesirDogru(parca, isaret) {
    const x0 = 40, x1 = 400, y = 46, st = (x1 - x0) / parca;
    let s = `<svg class="fig" viewBox="0 0 440 90"><line class="l" x1="${x0 - 15}" y1="${y}" x2="${x1 + 15}" y2="${y}"/>`;
    for (let i = 0; i <= parca; i++) { const x = x0 + i * st, t = i === 0 || i === parca; s += `<line class="l" x1="${x}" y1="${y - (t ? 9 : 5)}" x2="${x}" y2="${y + (t ? 9 : 5)}"/>`; if (t) s += `<text x="${x}" y="${y + 30}" text-anchor="middle">${i ? 1 : 0}</text>`; }
    for (const [k, l] of Object.entries(isaret)) s += `<circle cx="${x0 + k * st}" cy="${y}" r="7" class="fa"/><text x="${x0 + k * st}" y="${y - 14}" text-anchor="middle" class="a">${l}</text>`;
    return s + '</svg>';
  }
  function pist() {
    return `<svg class="fig sm" viewBox="0 0 360 170"><path d="M100 20 H260 A65 65 0 0 1 260 150 H100 A65 65 0 0 1 100 20 Z" class="fs bi" style="stroke-width:3"/><line class="ld" x1="100" y1="20" x2="100" y2="150"/><line class="ld" x1="260" y1="20" x2="260" y2="150"/><text x="180" y="14" text-anchor="middle">100 m</text><text x="180" y="166" text-anchor="middle">100 m</text><text x="92" y="90" text-anchor="end" class="m">60 m</text></svg>`;
  }
  function yamukBahce() {
    return `<svg class="fig sm" viewBox="0 0 360 180"><path d="M30 150 L330 150 L250 40 L90 40 Z" class="fg bi"/><line class="ld" x1="90" y1="40" x2="90" y2="150"/><path class="lm" d="M90 138 h12 v12"/><text x="180" y="172" text-anchor="middle">18 m</text><text x="170" y="32" text-anchor="middle">12 m</text><text x="84" y="100" text-anchor="end">8 m</text></svg>`;
  }

  /* ======================= DENEME 1 ======================= */
  const d1 = [
    // ---- TÜRKÇE ----
    Q('turkce', 'sozcukte-anlam', '"Tutmak" sözcüğü aşağıdakilerin hangisinde "bir şeye uygun düşmek, uymak" anlamında kullanılmıştır?', ['Kardeşimin elini sıkıca tuttu.', 'Bu hesap öbür hesapla tutmuyor.', 'Yağmur başlayınca taksi tuttuk.', 'Sınav öncesi heyecanını tutamadı.'], 1, '"Hesap tutmamak" iki hesabın birbirine <b>uymaması</b> demektir. Diğerlerinde tutmak; elle kavramak, kiralamak ve engellemek anlamındadır.'),
    Q('turkce', 'sozcukte-anlam', P('Ressam, tuvalin önünde saatlerce bekledi. Fırçası bir türlü kâğıda değmiyordu. Sonunda pencereden süzülen ışık, aradığı rengi ona <b>fısıldadı</b>.') + 'Bu metinde koyu yazılan sözcükle anlatılmak istenen aşağıdakilerden hangisidir?', ['Işığın ressama ilham vermesi', 'Ressamın sessizce konuşması', 'Pencerenin açık bırakılması', 'Rengin kaybolması'], 0, 'Işık gerçekte fısıldamaz; sözcük mecaz anlamda kullanılmıştır. Işığın ressamın aklına aradığı rengi getirmesi yani <b>ilham vermesi</b> anlatılmıştır.'),
    Q('turkce', 'cumlede-anlam', 'Aşağıdaki cümlelerin hangisinde <b>amaç</b> bildiren bir anlam vardır?', ['Kar yağdığı için okullar tatil edildi.', 'Düzenli çalışırsan hedefine ulaşırsın.', 'Kütüphaneye kitap iade etmek üzere gitti.', 'Hava kararınca sokak lambaları yandı.'], 2, '"İade etmek üzere" ifadesi gitme eyleminin <b>amacını</b> bildirir. Birinci cümle neden-sonuç, ikincisi koşul-sonuç, dördüncüsü zaman ilişkisidir.'),
    Q('turkce', 'cumlede-anlam', '"Yazar, yeni romanında okuru yormadan derinleşmeyi başarmış." cümlesinde yazarla ilgili aşağıdakilerden hangisi vurgulanmaktadır?', ['Eserlerinin çok uzun olduğu', 'Anlatımı ağır olduğu hâlde derin konuları işlediği', 'Derin konuları akıcı ve anlaşılır bir şekilde işlediği', 'Okurlarının sayısının azaldığı'], 2, '"Yormadan derinleşmek" derin konuları sıkmadan, <b>akıcı biçimde</b> anlatmaktır.'),
    Q('turkce', 'paragraf', P('Bir ağacın yaşını gövdesindeki halkalardan anlayabiliriz. Her yıl gövdeye yeni bir halka eklenir. Yağışlı yıllarda halkalar geniş, kurak yıllarda ise dar olur. Bu nedenle bilim insanları, yüzlerce yıllık ağaçların halkalarını inceleyerek geçmişteki iklim koşulları hakkında bilgi edinebilir.') + 'Bu metne göre aşağıdakilerden hangisi <b>söylenemez</b>?', ['Ağaçların gövdesine her yıl bir halka eklenir.', 'Halkaların genişliği yağış miktarıyla ilgilidir.', 'Halkalar sayesinde geçmişteki iklim hakkında bilgi edinilebilir.', 'Kurak yıllarda ağaçlara halka eklenmez.'], 3, 'Metne göre kurak yıllarda da halka eklenir, yalnızca <b>dar</b> olur. Bu yüzden "halka eklenmez" yargısı söylenemez.'),
    Q('turkce', 'paragraf', P('Çocukken dedemin bahçesinde domates yetiştirirdik. Fideleri dikerken dedem hep "Acele etme, toprak sabırlıyı sever." derdi. Her sabah sularken domateslerin bir gecede kızarmasını beklerdim ama onlar kendi zamanlarını bilirdi. Yıllar sonra anladım ki dedem bana yalnızca bahçıvanlığı değil, hayatı öğretiyormuş.') + 'Bu metinde asıl anlatılmak istenen aşağıdakilerden hangisidir?', ['Domates yetiştirmek uzun zaman alır.', 'Her işin bir zamanı vardır; sabırlı olmak gerekir.', 'Bahçeler her sabah sulanmalıdır.', 'Büyükler bahçe işlerinden hoşlanır.'], 1, 'Metindeki "toprak sabırlıyı sever" sözü ve domateslerin "kendi zamanlarını bilmesi" <b>sabır</b> mesajını verir. Son cümle bunun hayat için de geçerli olduğunu söyler.'),
    Q('turkce', 'paragraf', P('(I) Pek çok kuş türü sonbaharda sıcak bölgelere göç eder. (II) Bu yolculuk binlerce kilometre sürebilir. (III) Kuşlar yönlerini bulmak için Güneş\'ten, yıldızlardan ve Dünya\'nın manyetik alanından yararlanır. (IV) Kuş gözlemciliği son yıllarda popüler bir hobi hâline gelmiştir. (V) Bazı türler ise yol boyunca belirgin yer şekillerini takip eder.') + 'Bu metinde numaralanmış cümlelerden hangisi düşüncenin akışını bozmaktadır?', ['II', 'III', 'IV', 'V'], 2, 'Metin kuşların göçünü ve yön bulmasını anlatıyor. IV. cümle insanların hobisinden bahsederek konudan sapıyor.'),
    Q('turkce', 'paragraf', P('Okuduğumuz bir kitabı film olarak izlediğimizde çoğu zaman hayal kırıklığına uğrarız. Çünkü kitap okurken karakterlerin yüzlerini, seslerini, mekânları kendi hayal gücümüzle yaratırız. Film ise bize yönetmenin hayal ettiklerini sunar. Bu durumda zihnimizdeki görüntüyle ekrandaki görüntü çoğu zaman örtüşmez.') + 'Bu metinde aşağıdaki sorulardan hangisinin cevabı vardır?', ['Okurlar en çok hangi türdeki kitapları sever?', 'Kitaptan uyarlanan filmler neden çoğu zaman beğenilmez?', 'Bir filmin çekilmesi ne kadar sürer?', 'Yönetmenler senaryo yazarken nelere dikkat eder?'], 1, 'Metin, kitaptan uyarlanan filmlerin <b>neden</b> hayal kırıklığı yarattığını açıklar: zihnimizdeki görüntü ekrandakiyle örtüşmez.'),
    Q('turkce', 'paragraf', P('Bilim insanları, bir bitkinin yetiştiği toprağa kahve telvesi karıştırıldığında büyümesinin hızlandığını gözlemlemiştir. Ancak telve çok fazla kullanıldığında toprağın asitliği artmış ve bitkiler zarar görmüştür. Araştırmacılara göre doğru miktar, toprağın yaklaşık onda biri kadardır.') + 'Bu metinden hareketle aşağıdakilerden hangisine ulaşılabilir?', ['Kahve telvesi her bitki için zararlıdır.', 'Kahve telvesi ne kadar çok kullanılırsa bitki o kadar hızlı büyür.', 'Faydalı bir şey bile ölçüsüz kullanılırsa zarar verebilir.', 'Asitli toprak bitkilerin büyümesini hızlandırır.'], 2, 'Telve uygun miktarda faydalı, fazlası zararlıdır. Buradan <b>ölçünün önemli olduğu</b> sonucuna ulaşılır.'),
    Q('turkce', 'paragraf', P('Mektup yazmak bir zamanlar sabır isteyen bir uğraştı. İnsanlar duygularını kâğıda dökerken sözcüklerini özenle seçer, yazdıklarını defalarca okurdu. Mektubun cevabı ise haftalar sonra gelirdi. Bugün mesajlarımız saniyeler içinde ulaşıyor ama bu hız, yazdıklarımızın derinliğini azaltıyor.') + 'Bu metnin yazarıyla ilgili aşağıdakilerden hangisi söylenebilir?', ['Teknolojiye tamamen karşıdır.', 'Hızlı iletişimin yazıya özeni azalttığını düşünmektedir.', 'Mektupların artık hiç yazılmadığını savunmaktadır.', 'Mesajlaşmanın mektuptan daha samimi olduğunu belirtmektedir.'], 1, 'Yazar son cümlede hızın "yazdıklarımızın derinliğini azalttığını" söyler; yani <b>hızlı iletişimin özeni azalttığını</b> düşünür. Teknolojiye tamamen karşı olduğuna dair bir ifade yoktur.'),
    Q('turkce', 'paragraf', P('Dünya\'daki suyun yaklaşık %97\'si tuzlu sudur. Geriye kalan tatlı suyun da büyük bir kısmı buzullarda ve yer altında bulunur. İnsanların kolayca ulaşabildiği göl ve nehir suları ise tüm suyun yüzde birinden bile azdır.') + 'Bu metinde düşünceyi geliştirmek için aşağıdakilerden hangisine başvurulmuştur?', ['Tanık gösterme', 'Sayısal verilerden yararlanma', 'Benzetme', 'Karşılaştırma yapmadan örnekleme'], 1, '%97, yüzde bir gibi <b>sayısal veriler</b> kullanılmıştır.'),
    Q('turkce', 'fiiller', 'Aşağıdaki cümlelerin hangisinde fiil, kendi zaman anlamı dışında kullanılmıştır?', ['Her sabah yedide kalkarım.', 'Geçen yıl bu zamanlar köyde yaşıyorduk.', 'Haftaya bu saatte tatile çıkıyoruz.', 'Kardeşim şu anda ödevini yapıyor.'], 2, '"Çıkıyoruz" şimdiki zaman ekiyle çekimlenmiştir; "haftaya" sözü nedeniyle <b>gelecek zaman</b> anlamı taşır.'),
    Q('turkce', 'ek-fiil', P('Dedemin evi köyün en eski evi<b>ydi</b>. Bahçesinde dev bir ceviz ağacı vardı. Yazları bu ağacın gölgesinde otur<b>urduk</b>. Dedem bize eski zamanlardan hikâyeler anlat<b>ırdı</b>.') + 'Bu metinde koyu yazılan eklerle ilgili aşağıdakilerden hangisi söylenebilir?', ['Üçü de fiil kök ve gövdelerine gelmiştir.', 'Birincisi isim soylu bir sözcüğü yüklem yapmış; diğerleri birleşik zamanlı fiil oluşturmuştur.', 'Hepsi öğrenilen geçmiş zaman anlamı katmıştır.', 'Üçü de şart anlamı katmıştır.'], 1, '"Ev-iydi" isme gelen ek fiildir ve onu yüklem yapar. "Otur-ur-du-k" ve "anlat-ır-dı" ise geniş zamanın hikâyesi olan <b>birleşik zamanlı</b> fiillerdir.'),
    Q('turkce', 'zarflar', '"Konuşmasını <b>çok</b> heyecanlı bir sesle <b>ağır ağır</b> yaptı, <b>sonra</b> sahneden indi." cümlesindeki koyu yazılan sözcüklerin türleri sırasıyla aşağıdakilerin hangisinde doğru verilmiştir?', ['Miktar zarfı – Durum zarfı – Zaman zarfı', 'Durum zarfı – Miktar zarfı – Yer-yön zarfı', 'Sıfat – Durum zarfı – Zaman zarfı', 'Miktar zarfı – Zaman zarfı – Durum zarfı'], 0, '"Çok" sıfatın (heyecanlı) derecesini belirten <b>miktar zarfı</b>, "ağır ağır" fiilin nasıl yapıldığını anlatan <b>durum zarfı</b>, "sonra" ise <b>zaman zarfı</b>dır.'),
    Q('turkce', 'yazim', 'Aşağıdaki cümlelerin hangisinde <b>yazım yanlışı</b> yapılmıştır?', ['Bu kitabı birkaç kez okudum.', 'Sınavdan sonra herkes çok rahatladı.', 'Hiçbirşey söylemeden odadan çıktı.', 'Ankara\'ya her yaz gideriz.'], 2, '"Hiçbir şey" ayrı yazılır. "Birkaç" ise bitişik yazılır ve doğrudur.'),
    Q('turkce', 'soz-sanatlari', P('Rüzgâr, kapıyı tıklatıp "Beni içeri alın!" dedi.<br>Yapraklar ağlıyordu dallarından düşerken.<br>Bir damla yağmurla bütün şehir sel oldu.') + 'Bu dizelerde aşağıdaki söz sanatlarından hangisi <b>kullanılmamıştır</b>?', ['Konuşturma', 'Kişileştirme', 'Abartma', 'Benzetme'], 3, 'Rüzgârın konuşması <b>konuşturma</b>, yaprakların ağlaması <b>kişileştirme</b>, bir damla yağmurla şehrin sel olması <b>abartma</b>dır. "Gibi, kadar" ile yapılan bir benzetme yoktur: <b>benzetme</b> kullanılmamıştır.'),
    Q('turkce', 'anlatim-bozukluklari', 'Aşağıdaki cümlelerin hangisinde <b>anlatım bozukluğu yoktur</b>?', ['Toplantıya yaklaşık yirmi kişi kadar katıldı.', 'Aldığı ayakkabıyı geri iade etti.', 'Bu sorunu kesinlikle çözebiliriz belki.', 'Proje için bütün gün çalıştı.'], 3, 'Diğerlerinde "yaklaşık-kadar" ve "geri iade" gereksiz sözcük, "kesinlikle-belki" çelişki içerir. <b>"Proje için bütün gün çalıştı."</b> cümlesi doğrudur.'),
    Q('turkce', 'sozel-mantik', 'Bir okulun 7. sınıflarında yapılan kitap okuma yarışmasında sınıfların okuduğu kitap sayıları aşağıdaki grafikte verilmiştir.<br><br>Buna göre aşağıdakilerden hangisi <b>doğrudur</b>?', ['En çok kitabı 7-C okumuştur.', '7-A ile 7-D\'nin okuduğu kitap sayıları eşittir.', '7-B, 7-D\'nin iki katı kitap okumuştur.', 'Dört sınıfın okuduğu toplam kitap sayısı 160\'tır.'], 2, 'Grafiğe göre 7-A: 35, 7-B: 50, 7-C: 40, 7-D: 25. 7-B (50), 7-D\'nin (25) <b>iki katı</b>dır. En çok kitabı 7-B okumuştur; 7-A ile 7-D eşit değildir; toplam 35 + 50 + 40 + 25 = 150\'dir.', sutun([['7-A', 35], ['7-B', 50], ['7-C', 40], ['7-D', 25]], 60, 10, 'Kitap')),
    Q('turkce', 'sozel-mantik', 'Ece, Ferhat, Gül ve Hakan bir yarışmada matematik, tarih, fen ve müzik kategorilerinden farklı birer kategoride yarışmıştır.<br>• Ece müzik kategorisinde yarışmıştır.<br>• Ferhat fen kategorisinde yarışmıştır.<br>• Gül matematik kategorisinde yarışmamıştır.<br><br>Buna göre Gül hangi kategoride yarışmıştır?', ['Matematik', 'Tarih', 'Fen', 'Müzik'], 1, 'Ferhat fen, Ece müzik. Kalan matematik ve tarih Gül ile Hakan arasında paylaşılır. Gül matematik olamayacağına göre Gül <b>tarih</b>, Hakan matematik kategorisindedir.'),
    Q('turkce', 'sozel-mantik', 'Aşağıdaki tabloda bir kütüphanenin dört günlük ziyaretçi sayıları verilmiştir.' + tablo(['Gün', 'Öğrenci', 'Yetişkin'], [['Pazartesi', '40', '25'], ['Salı', '55', '20'], ['Çarşamba', '30', '35'], ['Perşembe', '45', '30']]) + 'Buna göre aşağıdakilerden hangisi <b>yanlıştır</b>?', ['Toplam ziyaretçinin en fazla olduğu gün perşembedir.', 'Yetişkin ziyaretçinin öğrenciden fazla olduğu tek gün çarşambadır.', 'Dört günde gelen öğrenci sayısı 170\'tir.', 'Salı günü gelen toplam ziyaretçi sayısı 75\'tir.'], 0, 'Günlük toplamlar: Pzt 65, Salı 75, Çar 65, Per 75. En fazla ziyaretçi salı ve perşembe <b>eşit</b>tir (75); "en fazla perşembe" ifadesi yanlıştır. Öğrenci toplamı 40 + 55 + 30 + 45 = 170\'tir.'),

    // ---- SOSYAL BİLGİLER ----
    Q('sosyal', 'iletisim', P('Sınıf başkanı Elif, arkadaşları arasında çıkan bir tartışmada iki tarafı da sözünü kesmeden dinledi. Ardından "Ben de sizin yerinizde olsam üzülürdüm." diyerek ikisinin de duygularını anladığını gösterdi.') + 'Elif\'in davranışında aşağıdakilerden hangisi öne çıkmaktadır?', ['Önyargı ve empati', 'Etkin dinleme ve empati', 'Sen dili ve suçlama', 'Emir verme ve yargılama'], 1, 'Sözü kesmeden dinlemek <b>etkin dinleme</b>, kendini onların yerine koymak <b>empati</b>dir.'),
    Q('sosyal', 'kurulus', 'Aşağıda Osmanlı Beyliği\'nin ilk dönemiyle ilgili bazı gelişmeler verilmiştir:<br>I. Bursa\'nın başkent yapılması<br>II. Bizans\'la yapılan ilk savaş olan Bafeus Savaşı<br>III. Ankara Savaşı\'ndan sonra Fetret Devri\'nin başlaması<br><br>Bu gelişmelerin kronolojik sıralaması aşağıdakilerden hangisidir?', ['I – II – III', 'II – I – III', 'II – III – I', 'III – I – II'], 1, 'Bafeus Savaşı 1302 (Osman Bey), Bursa\'nın alınması 1326 (Orhan Bey), Fetret Devri 1402 sonrası: <b>II – I – III</b>.'),
    Q('sosyal', 'yukselis', P('Bu padişah döneminde Osmanlı Devleti, Mercidabık ve Ridaniye savaşlarıyla Memlük Devleti\'ni yıkmış; kutsal emanetler İstanbul\'a getirilmiş ve halifelik Osmanlı\'ya geçmiştir.') + 'Metinde sözü edilen padişah kimdir?', ['Fatih Sultan Mehmet', 'Yavuz Sultan Selim', 'Kanuni Sultan Süleyman', 'II. Bayezid'], 1, 'Mercidabık (1516) ve Ridaniye (1517) <b>Yavuz Sultan Selim</b> dönemindedir.'),
    Q('sosyal', 'yukselis', 'Osmanlı Devleti\'nde tımar sisteminin uygulanmasıyla aşağıdakilerden hangisinin sağlanması amaçlanmamıştır?', ['Masrafsız olarak büyük bir atlı ordu beslenmesi', 'Tarımsal üretimin devamlılığı', 'Taşrada güvenliğin sağlanması', 'Denizlerde güçlü bir donanma kurulması'], 3, 'Tımar sistemi toprak, tarım, taşra güvenliği ve tımarlı sipahi ile ilgilidir; <b>donanma</b> kurulmasıyla doğrudan ilgisi yoktur.'),
    Q('sosyal', 'nufus', 'Aşağıdaki tabloda dört bölgenin bazı özellikleri verilmiştir.' + tablo(['Bölge', 'Özellik'], [['K', 'Kıyıda, ılıman iklim, liman ve sanayi tesisleri var'], ['L', 'Yüksek ve engebeli, kışlar uzun ve sert'], ['M', 'Geniş bir ovada, verimli tarım alanları var'], ['N', 'Çöl iklimine yakın, su kaynakları yetersiz']]) + 'Bu bölgelerden hangilerinin <b>seyrek</b> nüfuslu olması beklenir?', ['K ve L', 'K ve M', 'L ve N', 'M ve N'], 2, 'Engebeli ve sert iklimli <b>L</b> ile kurak ve susuz <b>N</b> seyrek nüfusludur.'),
    Q('sosyal', 'ekonomi', P('Bu kurumda mesleğe yeni başlayan gençler önce ustaların yanında çalışır, işi öğrenir; ardından kalfa olur. Ustalığa geçerken törenle kendilerine "şed" kuşatılır. Kurumun temel ilkeleri dürüstlük, cömertlik ve kaliteli üretimdir.') + 'Metinde sözü edilen kurum hangisidir?', ['Vakıf', 'Ahilik', 'Divan', 'Medrese'], 1, 'Çırak-kalfa-usta sistemi ve dürüstlük ilkeleri <b>Ahilik</b> teşkilatını anlatır.'),
    Q('sosyal', 'bilim', 'Aşağıdaki bilgin ve eser eşleştirmelerinden hangisi <b>doğrudur</b>?', ['İbn-i Sina – Kitab-ı Bahriye', 'Piri Reis – El-Kanun fi\'t-Tıb', 'Kaşgarlı Mahmud – Divanü Lügati\'t-Türk', 'Harezmi – Divan-ı Hikmet'], 2, '<b>Divanü Lügati\'t-Türk</b> Kaşgarlı Mahmud\'undur. Kitab-ı Bahriye Piri Reis\'in, El-Kanun İbn-i Sina\'nın, Divan-ı Hikmet Ahmet Yesevi\'nindir.'),
    Q('sosyal', 'vatandaslik', P('Bir mahkeme, verdiği kararda hiçbir kişi veya kurumdan emir ve talimat almaz; yalnızca Anayasa\'ya, kanunlara ve hukuka uygun olarak karar verir.') + 'Bu ifade aşağıdaki ilkelerden hangisiyle doğrudan ilgilidir?', ['Yargı bağımsızlığı', 'Yasama yetkisi', 'Yürütmenin denetimi', 'Seçme hakkı'], 0, 'Mahkemenin kimseden emir almaması <b>yargı bağımsızlığı</b>dır.'),
    Q('sosyal', 'vatandaslik', 'Aşağıdakilerden hangisi bir öğrencinin okulda <b>etkin vatandaşlık</b> davranışı göstermesine örnek değildir?', ['Okul meclisi seçiminde oy kullanması', 'Okul bahçesindeki çöpleri toplama kampanyasına katılması', 'Sınıf kurallarının belirlenmesinde görüş bildirmesi', 'Kütüphaneden aldığı kitabı geç iade etmesi'], 3, 'Kitabı geç iade etmek bir sorumluluğu yerine getirmemektir; etkin vatandaşlık örneği değildir.'),
    Q('sosyal', 'kuresel', P('15. yüzyılın sonlarında Avrupalı denizciler Afrika\'nın güneyini dolaşarak Hindistan\'a ulaşan yeni bir deniz yolu bulmuştur. Bu gelişmeden sonra Doğu\'nun mallarını Avrupa\'ya taşıyan kara yolları eski önemini yitirmeye başlamıştır.') + 'Bu metne göre aşağıdakilerden hangisi söylenebilir?', ['Coğrafi keşifler ticaret yollarının yönünü değiştirmiştir.', 'İpek Yolu bu dönemde daha da önem kazanmıştır.', 'Avrupalılar Hindistan\'a yalnızca kara yoluyla ulaşmıştır.', 'Deniz ticareti bu dönemde tamamen sona ermiştir.'], 0, 'Yeni deniz yolu bulununca kara yolları önemini kaybetmiştir; <b>ticaret yollarının yönü değişmiştir</b>.'),

    // ---- DİN KÜLTÜRÜ ----
    Q('din', 'melek-ahiret', 'Aşağıdaki melek ve görev eşleştirmelerinden hangisi <b>yanlıştır</b>?', ['Cebrail – Vahiy getirmek', 'Mikail – Tabiat olaylarını yönetmek', 'İsrafil – İnsanların amellerini yazmak', 'Azrail – Ruh almak'], 2, 'İsrafil <b>Sur\'a üfler</b>. Amelleri yazan melekler Kiramen Katibin\'dir.'),
    Q('din', 'melek-ahiret', P('Ahirete inanan bir insan, dünyada yaptığı her davranışın karşılığını göreceğini bilir. Bu nedenle gücü yettiği hâlde başkasının hakkını yemez; yalnız olduğunda bile doğru davranır.') + 'Bu metinde ahiret inancının hangi sonucu vurgulanmaktadır?', ['Bireyin davranışlarında sorumluluk bilinciyle hareket etmesi', 'İnsanın dünyadan tamamen el çekmesi', 'İnsanın yalnızca ibadetle ilgilenmesi', 'Kişinin geleceğinden endişe duyması'], 0, 'Her davranışın karşılığını göreceğini bilen kişi <b>sorumluluk bilinciyle</b> hareket eder.'),
    Q('din', 'hac-kurban', 'Haccın farzları ile ilgili aşağıdakilerden hangisi doğrudur?', ['Kurban kesmek haccın farzlarındandır.', 'İhram, Arafat vakfesi ve ziyaret tavafı haccın farzlarıdır.', 'Umre haccın farzlarından biridir.', 'Sa\'y ve şeytan taşlama haccın farzlarıdır.'], 1, 'Haccın farzları <b>ihram, Arafat vakfesi ve ziyaret tavafı</b>dır.'),
    Q('din', 'hac-kurban', P('Kurban Bayramı\'nda Ahmet\'in ailesi kestikleri kurbanın etini üçe ayırdı. Bir kısmını kendilerine ayırdı, bir kısmını komşu ve akrabalarına, bir kısmını da mahalledeki ihtiyaç sahibi ailelere dağıttı.') + 'Bu ailenin davranışı kurban ibadetinin daha çok hangi yönüyle ilişkilidir?', ['Paylaşma ve yardımlaşma', 'Ticari kazanç', 'Bireysel tasarruf', 'Gösteriş'], 0, 'Kurbanın etini akraba ve ihtiyaç sahipleriyle bölüşmek <b>paylaşma ve yardımlaşma</b>dır.'),
    Q('din', 'ahlak', 'Aşağıdaki davranışlardan hangisi <b>gıybet</b> örneğidir?', ['Bir arkadaşın yaptığı hatayı ona yüz yüze nazikçe söylemek', 'Bir arkadaşın, duyduğunda üzüleceği bir kusurunu onun yokluğunda başkalarına anlatmak', 'Bir arkadaşın başarısını herkesin önünde övmek', 'Bir arkadaşa ödevinde yardım etmek'], 1, 'Kişinin yokluğunda, duyduğunda hoşlanmayacağı şeyleri konuşmak <b>gıybet</b>tir.'),
    Q('din', 'ahlak', P('Okul servisinde yaşlı bir kadın ayakta kalınca Deniz hemen yerinden kalkıp ona yer verdi. Kadın teşekkür edince Deniz gülümseyerek "Rica ederim." dedi.') + 'Deniz\'in davranışı aşağıdaki değerlerden hangisiyle ilgilidir?', ['Saygı ve nezaket', 'Cimrilik', 'Kibir', 'İsraf'], 0, 'Yaşlıya yer vermek ve kibarca karşılık vermek <b>saygı ve nezaket</b>tir.'),
    Q('din', 'hz-muhammed', 'Aşağıdaki olaylardan hangisi Hz. Muhammed\'in (s.a.v.) peygamberlik <b>öncesi</b> hayatına aittir?', ['Hicret', 'Hilfü\'l-Fudûl\'a katılması', 'Mekke\'nin fethi', 'Veda Haccı'], 1, '<b>Hilfü\'l-Fudûl</b> peygamberlik öncesine aittir. Hicret (622), Mekke\'nin fethi (630) ve Veda Haccı (632) peygamberlik dönemindedir.'),
    Q('din', 'hz-muhammed', P('Peygamberler, Allah\'tan aldıkları vahyi hiçbir ekleme ya da çıkarma yapmadan, korkmadan ve çekinmeden insanlara iletmiştir.') + 'Metinde peygamberlerin hangi özelliği anlatılmaktadır?', ['Sıdk', 'Fetanet', 'İsmet', 'Tebliğ'], 3, 'Vahyi eksiksiz insanlara iletmek <b>tebliğ</b> sıfatıdır.'),
    Q('din', 'yorumlar', 'Aşağıdaki yorum ve alanı eşleştirmelerinden hangisi <b>yanlıştır</b>?', ['Maturidilik – İtikadi', 'Hanbelilik – Fıkhi', 'Yesevilik – Tasavvufi', 'Şafiilik – Tasavvufi'], 3, 'Şafiilik <b>fıkhi</b> bir mezheptir.'),
    Q('din', 'yorumlar', P('Bir hocanın öğrencileri, aynı ayeti farklı yaşam koşullarını da göz önüne alarak farklı şekillerde yorumlamış; ancak hepsi Kur\'an\'ı ve Hz. Peygamber\'in sünnetini temel almıştır.') + 'Bu durum dinî yorumlarla ilgili aşağıdakilerden hangisini gösterir?', ['Yorumlar dinin kendisidir.', 'Yorum farklılıkları ortak kaynaklara bağlı kalınarak ortaya çıkabilir.', 'Farklı yorumlar dinin temel kaynaklarını değiştirir.', 'Yalnızca tek bir yorum doğrudur.'], 1, 'Farklı yorumlar aynı kaynaklara (Kur\'an ve sünnet) bağlı kalınarak ortaya çıkmıştır.'),

    // ---- MATEMATİK ----
    Q('matematik', 'tam-sayilar', 'Sıcaklığı −18 °C olan bir dondurucunun elektriği kesiliyor. Dondurucunun içindeki sıcaklık her 10 dakikada 3 °C artmaktadır.<br><br>Elektrik kesildikten 1 saat sonra dondurucunun içindeki sıcaklık kaç °C olur?', ['−15', '−36', '0', '3'], 2, '1 saat = 60 dakika = 6 tane 10 dakika. Artış: 6 · 3 = 18 °C<br>−18 + 18 = <b>0 °C</b>'),
    Q('matematik', 'tam-sayilar', 'Bir bilgi yarışmasında her doğru cevap +4 puan, her yanlış cevap −3 puan, boş bırakılan her soru ise −1 puan olarak değerlendirilmektedir.<br><br>10 soruluk bu yarışmada 6 doğru, 3 yanlış cevap veren ve 1 soruyu boş bırakan Ece kaç puan almıştır?', ['14', '15', '24', '11'], 0, '6 · 4 + 3 · (−3) + 1 · (−1) = 24 − 9 − 1 = <b>14</b>'),
    Q('matematik', 'rasyonel', '1,5 litrelik bir su şişesinin önce ' + F(2, 5) + '\'i içiliyor. Ardından şişeden 0,3 litre daha su içiliyor.<br><br>Şişede kaç litre su kalmıştır?', ['0,9', '0,6', '0,3', '0,75'], 1, 'İlk içilen: 1,5 · ' + F(2, 5) + ' = 0,6 L<br>Kalan: 1,5 − 0,6 − 0,3 = <b>0,6 L</b>'),
    Q('matematik', 'rasyonel', 'Aşağıdaki sayı doğrusunda 0 ile 1 arası eş parçalara ayrılmıştır.<br><br>Buna göre K ve L noktaları arasındaki uzaklık kaç birimdir?', [F(1, 2), F(1, 3), F(2, 3), F(5, 6)], 0, 'Birim 6 eş parçaya ayrılmış. K = ' + F(2, 6) + ', L = ' + F(5, 6) + '<br>Uzaklık: ' + F(5, 6) + ' − ' + F(2, 6) + ' = ' + F(3, 6) + ' = <b>' + F(1, 2) + '</b>', kesirDogru(6, { 2: 'K', 5: 'L' })),
    Q('matematik', 'cebirsel', 'Bir kenar uzunluğu x metre olan kare şeklindeki bir bahçenin bir kenarı 3 m uzatılıyor, diğer kenarı ise 2 m kısaltılarak dikdörtgen şeklinde yeni bir bahçe elde ediliyor.<br><br>Yeni bahçenin çevresini metre cinsinden gösteren cebirsel ifade aşağıdakilerden hangisidir?', ['4x + 1', '4x + 2', '2x + 1', '4x + 10'], 1, 'Yeni kenarlar: (x + 3) ve (x − 2)<br>Çevre = 2 · (x + 3 + x − 2) = 2 · (2x + 1) = <b>4x + 2</b>'),
    Q('matematik', 'cebirsel', 'Bir kafede kare masalar yan yana birleştirilerek uzun bir masa oluşturuluyor. 1 masaya 6 kişi, yan yana 2 masaya 10 kişi, 3 masaya 14 kişi oturabilmektedir.<br><br>Bu şekilde yan yana birleştirilen masalara 50 öğrencinin oturabilmesi için en az kaç masa gerekir?', ['11', '12', '13', '25'], 1, 'Kişi sayıları 6, 10, 14, … → her masa 4 kişi ekliyor: <b>4n + 2</b><br>4n + 2 ≥ 50 → 4n ≥ 48 → n ≥ 12. En az <b>12</b> masa.'),
    Q('matematik', 'denklem', 'Ali\'nin parası Ayşe\'nin parasının 2 katıdır. Ali, Ayşe\'ye 30 TL verdiğinde ikisinin paraları eşit oluyor.<br><br>Ayşe\'nin başlangıçta kaç TL parası vardır?', ['30', '45', '60', '120'], 2, 'Ayşe: x, Ali: 2x. 2x − 30 = x + 30 → <b>x = 60</b>'),
    Q('matematik', 'denklem', 'Eşit kollu bir terazinin sol kefesinde 3 özdeş top ve 2 kg\'lık bir ağırlık, sağ kefesinde 1 özdeş top ve 8 kg\'lık bir ağırlık vardır ve terazi dengededir.<br><br>Sol kefeye 1 top daha eklendiğinde dengenin yeniden sağlanması için sağ kefeye kaç kg ağırlık eklenmelidir?', ['2', '3', '4', '6'], 1, '3t + 2 = t + 8 → 2t = 6 → t = 3 kg<br>Sol kefeye bir top (3 kg) eklenince sağa da <b>3 kg</b> eklenmelidir.'),
    Q('matematik', 'oran-oranti', 'Ölçeği 1 : 200 000 olan bir haritada iki köy arasındaki uzaklık 4,5 cm olarak ölçülmüştür.<br><br>Bu iki köy arasındaki gerçek uzaklık kaç km\'dir?', ['4,5', '9', '45', '90'], 1, '1 cm → 200 000 cm = 2 km. 4,5 cm → 4,5 · 2 = <b>9 km</b>'),
    Q('matematik', 'oran-oranti', 'Aynı güçteki 3 musluk boş bir havuzu birlikte 12 saatte doldurabilmektedir. Musluklar birlikte açıldıktan 2 saat sonra aynı güçte 1 musluk daha açılıyor.<br><br>Havuzun tamamen dolması için bundan sonra kaç saat geçmesi gerekir?', ['7,5', '8', '9', '10'], 0, 'Toplam iş: 3 · 12 = 36 birim. 2 saatte 3 · 2 = 6 birim doldu, 30 birim kaldı.<br>4 musluk: 30 : 4 = <b>7,5 saat</b>'),
    Q('matematik', 'yuzdeler', 'Bir mağaza "4 al 3 öde" kampanyası yapmaktadır. Tüm ürünlerin fiyatı aynıdır.<br><br>Bu kampanyadan 4 ürün alan bir müşteri yüzde kaç indirim kazanmış olur?', ['%20', '%25', '%30', '%33'], 1, '4 ürünün 1\'i ücretsiz: ' + F(1, 4) + ' = <b>%25</b>'),
    Q('matematik', 'yuzdeler', 'Bir kitapçı, maliyeti 80 TL olan bir kitabı %25 kârla etikete yazıyor. Kampanya döneminde ise etiket fiyatı üzerinden %20 indirim yapıyor.<br><br>Kitapçının kampanya döneminde bu kitabı satmasıyla ilgili aşağıdakilerden hangisi doğrudur?', ['Ne kâr ne zarar eder.', '%5 kâr eder.', '%5 zarar eder.', '%20 zarar eder.'], 0, 'Etiket fiyatı: 80 · 1,25 = 100 TL<br>İndirimli fiyat: 100 · 0,8 = 80 TL = maliyet → <b>ne kâr ne zarar</b>'),
    Q('matematik', 'acilar', 'Bir duvar saati 2.00\'yi gösterirken akrep ile yelkovan arasındaki küçük açının <b>tümleri</b> kaç derecedir? (Saat kadranı 12 eş parçaya ayrılmıştır.)', ['30', '60', '120', '150'], 0, 'Her saat aralığı 360 : 12 = 30°. Saat 2.00\'de açı 2 · 30 = 60°.<br>Tümleri: 90 − 60 = <b>30°</b>'),
    Q('matematik', 'acilar', 'Şekilde d₁ ∥ d₂ olduğuna göre x kaçtır?', ['25', '30', '35', '45'], 1, '(3x + 15)° dar açı, (2x + 15)° geniş açı konumundadır. Paralel doğrularda dar ve geniş açı bütünlerdir:<br>3x + 15 + 2x + 15 = 180 → 5x = 150 → <b>x = 30</b>', paralel({ UR: '(3x + 15)°' }, { LR: '(2x + 15)°' })),
    Q('matematik', 'cokgenler', 'Bir düzgün çokgenin bir dış açısının ölçüsü, bir iç açısının ölçüsünün ' + F(1, 3) + '\'ü kadardır.<br><br>Bu çokgen kaç kenarlıdır?', ['6', '8', '9', '12'], 1, 'Dış açı d, iç açı 3d. d + 3d = 180 → d = 45°<br>n = 360 : 45 = <b>8</b>'),
    Q('matematik', 'cokgenler', 'Yamuk şeklindeki bir bahçenin ölçüleri şekilde verilmiştir. Bahçenin her metrekaresine 2 kg gübre atılacaktır.<br><br>Bahçe için toplam kaç kg gübre gerekir?', ['120', '144', '240', '480'], 2, 'Alan = ' + F('(18 + 12)', 2) + ' · 8 = 120 m²<br>Gübre: 120 · 2 = <b>240 kg</b>', yamukBahce()),
    Q('matematik', 'cember', 'Şekildeki koşu pisti, uzunlukları 100 m olan iki doğru parça ile çapı 60 m olan iki yarım çemberden oluşmaktadır.<br><br>Bu pistin çevresinde 1 tur atan bir sporcu kaç metre koşar? (π = 3 alınız.)', ['260', '380', '560', '300'], 1, 'İki yarım çember = 1 tam çember: 3 · 60 = 180 m<br>Toplam: 100 + 100 + 180 = <b>380 m</b>', pist()),
    Q('matematik', 'cember', 'Bir duvar saatinin yelkovanı 12 cm uzunluğundadır.<br><br>20 dakikada yelkovanın ucunun aldığı yol kaç cm\'dir? (π = 3 alınız.)', ['12', '18', '24', '36'], 2, '20 dakikada yelkovan ' + F(20, 60) + ' = ' + F(1, 3) + ' tur döner.<br>Yol: 2 · 3 · 12 · ' + F(1, 3) + ' = <b>24 cm</b>'),
    Q('matematik', 'veri', 'Bir grupta 5 öğrencinin matematik sınavından aldığı notların aritmetik ortalaması 75\'tir. Gruba katılan altıncı öğrencinin notuyla birlikte ortalama 78 oluyor.<br><br>Altıncı öğrencinin notu kaçtır?', ['78', '81', '90', '93'], 3, '5 öğrencinin toplamı: 5 · 75 = 375. 6 öğrencinin toplamı: 6 · 78 = 468<br>Altıncı öğrencinin notu: 468 − 375 = <b>93</b>'),
    Q('matematik', 'veri', 'Aylık geliri 24 000 TL olan bir ailenin harcamaları aşağıdaki daire grafiğinde gösterilmiştir.<br><br>Bu ailenin kira harcaması, gıda harcamasından kaç TL fazladır?', ['1000', '2000', '3000', '6000'], 1, 'Kira 120°, gıda 90° → fark 30°<br>24 000 · ' + F(30, 360) + ' = <b>2000 TL</b>', pasta([['Kira', 120, '120°'], ['Gıda', 90, '90°'], ['Ulaşım', 60, '60°'], ['Diğer', 90, '90°']]))
  ];

  /* ======================= DENEME 2 ======================= */
  const d2 = [
    // ---- TÜRKÇE ----
    Q('turkce', 'sozcukte-anlam', 'Aşağıdaki cümlelerin hangisinde "kırılmak" sözcüğü <b>mecaz</b> anlamda kullanılmıştır?', ['Masadan düşen bardak kırıldı.', 'Fırtınada ağacın dalı kırıldı.', 'Arkadaşının sözlerine çok kırıldı.', 'Pencerenin camı topla kırıldı.'], 2, '"Sözlere kırılmak" gücenmek anlamındadır; <b>mecazdır</b>.'),
    Q('turkce', 'sozcukte-anlam', '"Ağzı kulaklarına varmak" deyiminin anlamına en yakın cümle hangisidir?', ['Haberi duyunca çok sevindi.', 'Haberi duyunca çok korktu.', 'Haberi duyunca konuşmadı.', 'Haberi duyunca bağırdı.'], 0, 'Deyim <b>çok sevinmek</b> anlamındadır.'),
    Q('turkce', 'cumlede-anlam', 'Aşağıdaki cümlelerin hangisinde <b>öznel</b> bir yargı vardır?', ['Türkiye\'nin en uzun nehri Kızılırmak\'tır.', 'Bu yıl okulumuzda 450 öğrenci var.', 'Sonbahar, yılın en hüzünlü mevsimidir.', 'Su 100 °C\'de kaynar.'], 2, '"En hüzünlü mevsim" kişiden kişiye değişen bir görüştür: <b>öznel</b>.'),
    Q('turkce', 'cumlede-anlam', '"Takımımız, son dakikaya kadar mücadele etmesine karşın maçı kaybetti." cümlesindeki anlam ilişkisi aşağıdakilerden hangisinde vardır?', ['Çok yorulduğu için erken yattı.', 'Bütün gün yağmur yağmasına rağmen piknik iptal edilmedi.', 'Sınava hazırlanmak için kütüphaneye gitti.', 'Yarın hava güzel olursa denize gideriz.'], 1, 'İki cümlede de "karşın / rağmen" ile <b>beklenmeyen bir sonuç</b> anlatılmıştır.'),
    Q('turkce', 'paragraf', P('Ormanlarda yaşayan karıncalar, düşen yaprakları ve ölü böcekleri yuvalarına taşır. Bu sayede toprağa besin karışır, toprak havalanır. Bazı bitkilerin tohumlarını da uzak yerlere taşıyarak bitkilerin yayılmasına yardım ederler. Küçücük bedenleriyle karıncalar, ormanın sağlığı için büyük bir iş görür.') + 'Bu metnin konusu aşağıdakilerden hangisidir?', ['Karıncaların beslenme alışkanlıkları', 'Karıncaların orman ekosistemine katkısı', 'Ormanlardaki bitki türleri', 'Karıncaların yuva yapma biçimleri'], 1, 'Metin karıncaların toprağa, bitkilere ve ormanın sağlığına <b>katkısını</b> anlatır.'),
    Q('turkce', 'paragraf', P('Bir sporcunun başarısı yalnızca yarışma günündeki performansıyla ölçülmez. Kimsenin görmediği sabah antrenmanları, sakatlıktan sonra yeniden başlama cesareti ve yenilgilerden çıkarılan dersler de bu başarının parçasıdır. Madalya, aslında görünmeyen bu emeğin görünen yüzüdür.') + 'Bu metnin ana düşüncesi aşağıdakilerden hangisidir?', ['Sporcular madalya almak için yarışır.', 'Başarının arkasında görünmeyen uzun bir emek vardır.', 'Sakatlıklar sporcuların kariyerini bitirir.', 'Sabah antrenmanları akşamdakilerden daha verimlidir.'], 1, 'Son cümle ana düşünceyi özetler: Madalya <b>görünmeyen emeğin</b> sonucudur.'),
    Q('turkce', 'paragraf', P('(I) Eski İstanbul evleri genellikle ahşaptan yapılırdı. (II) Bu evlerin cumbaları sokağa doğru taşar, sokakları daha canlı gösterirdi. (III) Ahşap, depremlerde esneyerek binanın yıkılmasını zorlaştırırdı. (IV) Ancak bu evler yangınlara karşı oldukça savunmasızdı. (V) Nitekim tarih boyunca çıkan büyük yangınlarda pek çok mahalle tamamen yok olmuştur.') + 'Bu metin iki paragrafa ayrılmak istenirse ikinci paragraf hangi cümleyle başlar?', ['II', 'III', 'IV', 'V'], 2, 'I-III ahşap evlerin özelliklerini ve <b>avantajlarını</b>, IV-V ise <b>dezavantajını</b> (yangın) anlatır. "Ancak" ile başlayan IV. cümle yeni paragrafın başıdır.'),
    Q('turkce', 'paragraf', P('Teknoloji hayatımızı kolaylaştırırken bazı becerilerimizi de zayıflatabiliyor. Örneğin telefon numaralarını artık ezberlemiyoruz; yol tarifini haritalara bırakıyoruz; basit hesapları bile hesap makinesiyle yapıyoruz. Bu kolaylıklardan vazgeçmek gerekmez ama zihnimizi çalıştırmayı da ihmal etmemeliyiz.') + 'Bu metinde aşağıdaki düşünceyi geliştirme yollarından hangisi kullanılmıştır?', ['Örneklendirme', 'Tanık gösterme', 'Sayısal verilerden yararlanma', 'Tanımlama'], 0, '"Örneğin" ile telefon numarası, yol tarifi ve hesap makinesi <b>örnekleri</b> verilmiştir.'),
    Q('turkce', 'paragraf', P('Ressam Leyla Hanım, resimlerinde hep doğup büyüdüğü Karadeniz köyünü anlatır. Yeşilin her tonunu tuvaline taşıyan sanatçı, yağmurun bile renginin olduğuna inanır. Ona göre bir ressam, ancak çok iyi tanıdığı ve sevdiği yerleri gerçekten resmedebilir.') + 'Bu metne göre Leyla Hanım\'la ilgili aşağıdakilerden hangisi <b>söylenemez</b>?', ['Resimlerinde memleketini konu edinir.', 'Resimlerinde yeşil rengin farklı tonlarını kullanır.', 'Sanatçının iyi tanıdığı yerleri resmetmesi gerektiğini düşünür.', 'Resimlerini yalnızca yağmurlu günlerde yapar.'], 3, 'Metinde ressamın yalnızca yağmurlu günlerde resim yaptığına dair bir bilgi yoktur.'),
    Q('turkce', 'paragraf', P('Bazı insanlar hata yapmaktan o kadar korkar ki hiç denemezler. Oysa hata, öğrenmenin doğal bir parçasıdır. Bisiklet sürmeyi düşe kalka öğreniriz; her düşüşte dengemizi biraz daha iyi kurarız. Hiç düşmeyen biri, belki de hiç bisiklete binmemiştir.') + 'Bu metinden aşağıdakilerin hangisi çıkarılabilir?', ['Bisiklet sürmek tehlikelidir.', 'Hata yapmaktan korkmak gelişmeyi engeller.', 'İnsanlar hata yapmamaya özen göstermelidir.', 'Başarılı olanlar hiç hata yapmaz.'], 1, 'Yazar hatanın öğrenmenin parçası olduğunu, korkup denemeyenlerin öğrenemeyeceğini anlatır: <b>hata korkusu gelişmeyi engeller</b>.'),
    Q('turkce', 'paragraf', P('Bir şehrin kimliği yalnızca büyük yapılarında değil, küçük ayrıntılarında da saklıdır. Bir çeşmenin üzerindeki yazı, eski bir kapının tokmağı, bir sokağın taş döşemesi o şehrin geçmişini fısıldar. Bu yüzden şehirleri tanımak isteyenler, ana caddelerden çok ara sokaklara bakmalıdır.') + 'Bu metne en uygun başlık aşağıdakilerden hangisidir?', ['Büyük Yapılar', 'Şehirlerin Ayrıntılarda Saklı Kimliği', 'Ana Caddelerin Önemi', 'Çeşmelerin Tarihi'], 1, 'Metin şehrin kimliğinin <b>küçük ayrıntılarda</b> saklı olduğunu anlatır.'),
    Q('turkce', 'fiiller', P('Sabah erkenden yola <b>çıktık</b>. Yolda dedem bize eski bir masal <b>anlattı</b>. Akşam köye <b>varacağız</b>. Keşke yolculuk hiç <b>bitmese</b>.') + 'Bu metinde koyu yazılan fiillerin kipleri ile ilgili aşağıdakilerden hangisi doğrudur?', ['Hepsi haber kipiyle çekimlenmiştir.', 'Üçü haber, biri dilek kipiyle çekimlenmiştir.', 'İkisi haber, ikisi dilek kipiyle çekimlenmiştir.', 'Hepsi dilek kipiyle çekimlenmiştir.'], 1, 'çıktık, anlattı (görülen geçmiş), varacağız (gelecek) → haber kipi; bitmese → dilek-şart. <b>Üç haber, bir dilek</b>.'),
    Q('turkce', 'ek-fiil', 'Aşağıdaki cümlelerin hangisinde ek fiil <b>şart</b> anlamı katmıştır?', ['Hava güzelse parka gideriz.', 'Dün hava çok güzeldi.', 'O gün hava güzelmiş.', 'Hava her zaman güzeldir.'], 0, '"Güzel-se" → ek fiilin <b>şart</b> kipi. Diğerleri hikâye, rivayet ve genellik (-dir) anlamlıdır.'),
    Q('turkce', 'zarflar', 'Aşağıdaki cümlelerin hangisinde <b>yer-yön zarfı</b> kullanılmıştır?', ['Kediler bahçede oynuyordu.', 'Çocuklar yukarı koştu.', 'Yukarıdaki kat boş.', 'Aşağıya bir masa koyduk.'], 1, '"Yukarı" sözcüğü ek almadan fiili (koştu) yön bakımından belirtmiştir: <b>yer-yön zarfı</b>. "Yukarıdaki" ve "aşağıya" ek aldığı için isimdir.'),
    Q('turkce', 'yazim', 'Aşağıdaki cümlelerin hangisinde noktalama işaretiyle ilgili bir <b>yanlışlık</b> yapılmıştır?', ['Kitap, defter ve kalem aldım.', 'Eyvah, otobüsü kaçırdık!', 'Annem bana sordu: "Ödevini bitirdin mi?"', 'Yarın okula gidecek misin.'], 3, 'Soru bildiren cümlenin sonuna <b>soru işareti</b> konmalıdır: "Yarın okula gidecek misin?"'),
    Q('turkce', 'soz-sanatlari', '"Bulutlar, dağların başına pamuktan bir şapka gibi oturmuştu." cümlesinde aşağıdaki söz sanatlarından hangileri vardır?', ['Benzetme ve kişileştirme', 'Abartma ve konuşturma', 'Yalnızca konuşturma', 'Yalnızca abartma'], 0, 'Bulutlar "gibi" ile pamuk şapkaya benzetilmiş (<b>benzetme</b>); dağlara "baş" verilmiş, şapka giymişler gibi gösterilmiştir (<b>kişileştirme</b>).'),
    Q('turkce', 'anlatim-bozukluklari', '"Bu konuyu daha önce defalarca, birçok kez anlatmıştım." cümlesindeki anlatım bozukluğunun nedeni aşağıdakilerden hangisidir?', ['Anlamca çelişen sözcüklerin kullanılması', 'Aynı anlama gelen sözcüklerin bir arada kullanılması', 'Bir sözcüğün yanlış anlamda kullanılması', 'Deyimin yanlış kullanılması'], 1, '"Defalarca" ve "birçok kez" aynı anlamdadır; biri <b>gereksizdir</b>.'),
    Q('turkce', 'sozel-mantik', 'Beş arkadaş (Arda, Berk, Can, Duru, Ela) bir sinema salonunda aynı sırada yan yana oturmuştur.<br>• Duru, en sağdaki koltukta oturmaktadır.<br>• Arda ile Berk yan yanadır ve Arda, Berk\'in solundadır.<br>• Can, ortadaki koltukta oturmaktadır.<br>• Ela, Duru\'nun hemen solundadır.<br><br>Buna göre en soldaki koltukta kim oturmaktadır?', ['Arda', 'Berk', 'Can', 'Ela'], 0, 'Duru 5, Ela 4, Can 3. Arda ve Berk yan yana ve Arda solda → Arda 1, Berk 2. En solda <b>Arda</b>.'),
    Q('turkce', 'sozel-mantik', 'Aşağıdaki grafikte bir öğrencinin bir hafta boyunca kitap okumaya ayırdığı süreler (dakika) verilmiştir.<br><br>Buna göre aşağıdakilerden hangisi <b>yanlıştır</b>?', ['En uzun süre perşembe günü okunmuştur.', 'Salı ve cuma günlerinde okunan süreler toplamı 90 dakikadır.', 'Çarşamba günü pazartesiden 10 dakika az okunmuştur.', 'Hafta boyunca toplam 180 dakika okunmuştur.'], 1, 'Pzt 30, Salı 45, Çar 20, Per 50, Cuma 35. Salı + Cuma = 45 + 35 = <b>80</b> dakikadır, 90 değil. Diğer ifadeler doğrudur: çarşamba pazartesiden 10 dk az, toplam 180 dk, en uzun perşembe.', sutun([['Pzt', 30], ['Salı', 45], ['Çar', 20], ['Per', 50], ['Cuma', 35]], 60, 10, 'Dakika')),
    Q('turkce', 'sozel-mantik', 'Bir okulda dört kulübün toplantı günleri belirlenecektir. Kulüpler; satranç, drama, robotik ve müzik kulüpleridir. Toplantılar pazartesiden perşembeye kadar her gün bir kulüp olacak şekilde yapılacaktır.<br>• Robotik kulübü salı günü toplanacaktır.<br>• Drama kulübü, müzik kulübünden hemen sonraki gün toplanacaktır.<br>• Satranç kulübü perşembe günü toplanmayacaktır.<br><br>Buna göre drama kulübü hangi gün toplanacaktır?', ['Pazartesi', 'Salı', 'Çarşamba', 'Perşembe'], 3, 'Salı robotik. Müzik ve drama ardışık günlerde olmalı ve salıya denk gelmemeli: pazartesi-salı ve salı-çarşamba olamaz. Tek seçenek müzik çarşamba, drama <b>perşembe</b>. Satranç pazartesiye kalır.'),

    // ---- SOSYAL BİLGİLER ----
    Q('sosyal', 'iletisim', 'Aşağıdaki ifadelerden hangisi <b>sen dili</b> ile kurulmuştur?', ['Toplantıya geç kalınca endişelendim.', 'Sen hep sözünü tutmazsın!', 'Sesini yükseltince ne hissedeceğimi bilemiyorum.', 'Eşyalarım dağıtılınca üzülüyorum.'], 1, '"Sen hep sözünü tutmazsın!" karşıdakini suçlayan <b>sen dili</b>dir. Diğerleri kişinin kendi duygusunu anlattığı ben dilidir.'),
    Q('sosyal', 'kurulus', P('Bu savaşta Büyük Selçuklu Sultanı Alparslan, Bizans İmparatoru Romen Diyojen\'i yenmiştir. Savaştan sonra Türkler Anadolu\'ya yoğun olarak yerleşmeye başlamıştır.') + 'Metinde sözü edilen savaş hangisidir?', ['Miryokefalon', 'Malazgirt', 'Kösedağ', 'Ankara'], 1, 'Alparslan\'ın Romen Diyojen\'i yendiği savaş 1071 <b>Malazgirt</b>\'tir.'),
    Q('sosyal', 'kurulus', 'Aşağıdakilerden hangisi Osmanlı Beyliği\'nin kısa sürede büyümesinin nedenlerinden biri <b>değildir</b>?', ['Bizans sınırında kurulmuş olması', 'Fethedilen yerlerde adaletli bir yönetim uygulaması', 'Kurulduğu dönemde Anadolu\'daki en güçlü beylik olması', 'Gaza ve cihat anlayışını benimsemesi'], 2, 'Osmanlı kurulduğunda küçük bir beylikti; Anadolu\'nun <b>en güçlü</b> beyliği değildi.'),
    Q('sosyal', 'yukselis', 'Aşağıdaki olaylardan hangisi Kanuni Sultan Süleyman dönemine <b>ait değildir</b>?', ['Belgrad\'ın fethi', 'Rodos\'un fethi', 'Preveze Deniz Zaferi', 'İstanbul\'un fethi'], 3, 'İstanbul 1453\'te <b>Fatih Sultan Mehmet</b> tarafından fethedilmiştir.'),
    Q('sosyal', 'nufus', P('Doğu Karadeniz\'de bir köyde yaşayan Mehmet Bey, yazları ailesiyle birlikte hayvanlarını otlatmak için yaylaya çıkmakta, sonbaharda yeniden köyüne dönmektedir.') + 'Mehmet Bey\'in yaptığı göç aşağıdakilerden hangisidir?', ['Beyin göçü', 'Mevsimlik iç göç', 'Dış göç', 'Zorunlu göç'], 1, 'Ülke içinde, belirli mevsimlerde yapılan ve geri dönülen göç <b>mevsimlik iç göç</b>tür.'),
    Q('sosyal', 'ekonomi', 'Osmanlı döneminde yaptırılan aşağıdaki yapılardan hangisi <b>sağlık</b> hizmeti vermek amacıyla kurulmuştur?', ['İmaret', 'Darüşşifa', 'Kervansaray', 'Bedesten'], 1, '<b>Darüşşifa</b> hastanedir. İmaret aşevi, kervansaray konaklama yeri, bedesten değerli eşyaların satıldığı çarşıdır.'),
    Q('sosyal', 'bilim', 'Aşağıdaki gelişmelerden hangisi bilginin daha geniş kitlelere ulaşmasında <b>en etkili</b> olmuştur?', ['Matbaanın icadı', 'Pusulanın kullanılması', 'Barutun bulunması', 'Tekerleğin icadı'], 0, '<b>Matbaa</b> kitapların hızlı ve ucuz çoğaltılmasını sağlayarak bilgiyi yaygınlaştırmıştır.'),
    Q('sosyal', 'vatandaslik', 'Aşağıdakilerden hangisi <b>yürütme</b> organına ait bir görevdir?', ['Kanun yapmak', 'Kanunları uygulamak', 'Davaları karara bağlamak', 'Milletvekili seçmek'], 1, 'Yürütme organı (Cumhurbaşkanı) <b>kanunları uygular</b>. Kanun yapmak yasamanın, dava görmek yargının görevidir.'),
    Q('sosyal', 'kuresel', P('İkinci Dünya Savaşı\'nın büyük yıkımından sonra devletler, benzer savaşların yeniden yaşanmaması ve dünya barışının korunması amacıyla 1945\'te bir araya gelerek bir kuruluş oluşturmuştur.') + 'Metinde sözü edilen kuruluş hangisidir?', ['NATO', 'Birleşmiş Milletler', 'Türk Devletleri Teşkilatı', 'İslam İşbirliği Teşkilatı'], 1, '1945\'te dünya barışını korumak için kurulan kuruluş <b>Birleşmiş Milletler</b>\'dir.'),
    Q('sosyal', 'iletisim', 'Aşağıdakilerden hangisi kişisel verilerin korunması açısından <b>doğru</b> bir davranıştır?', ['Sosyal medyada ev adresini paylaşmak', 'Şifresini arkadaşlarıyla paylaşmak', 'Tanımadığı kişilerden gelen bağlantılara tıklamamak', 'Kimlik bilgilerini her siteye girmek'], 2, 'Tanımadığı kişilerden gelen bağlantılara <b>tıklamamak</b> kişisel bilgileri korur.'),

    // ---- DİN KÜLTÜRÜ ----
    Q('din', 'melek-ahiret', 'Ahiret hayatıyla ilgili kavramlardan hangisi "insanların amellerinin tartılması" anlamına gelir?', ['Ba\'s', 'Haşr', 'Mizan', 'Sırat'], 2, 'Amellerin tartılmasına <b>mizan</b> denir.'),
    Q('din', 'melek-ahiret', 'Aşağıdakilerden hangisi cinlerin özelliklerinden biri <b>değildir</b>?', ['Ateşten yaratılmışlardır.', 'Akıl ve irade sahibidirler.', 'İçlerinde iyi ve kötü olanlar vardır.', 'Nurdan yaratılmışlardır ve hiç günah işlemezler.'], 3, 'Nurdan yaratılan ve günah işlemeyen varlıklar <b>meleklerdir</b>.'),
    Q('din', 'hac-kurban', 'Belirli günler dışında yılın her zamanında yapılabilen Kâbe ziyaretine ne ad verilir?', ['Hac', 'Umre', 'Vakfe', 'Tavaf'], 1, 'Zaman sınırı olmadan yapılan ziyaret <b>umre</b>dir.'),
    Q('din', 'hac-kurban', 'Aşağıdaki hayvanlardan hangisine birden fazla kişi ortak olarak kurban kesebilir?', ['Koyun', 'Keçi', 'Sığır', 'Kuzu'], 2, 'Sığır, manda, deve gibi büyükbaş hayvanlara <b>7 kişiye kadar</b> ortak olunabilir.'),
    Q('din', 'ahlak', P('Bir esnaf, sattığı ürünün kusurunu müşterisinden gizlemeyip "Bu ürünün bir kusuru var, isterseniz başka bir ürün göstereyim." demiştir.') + 'Esnafın bu davranışı aşağıdaki değerlerden hangisiyle ilgilidir?', ['Dürüstlük', 'Cömertlik', 'Sabır', 'Tasarruf'], 0, 'Kusuru gizlememek <b>dürüstlük</b>tür.'),
    Q('din', 'ahlak', 'Aşağıdakilerden hangisi İslam\'da <b>övülen</b> davranışlardan biri değildir?', ['Selamlaşmak', 'Haset etmek', 'Yardımlaşmak', 'Sözünde durmak'], 1, '<b>Haset</b> (kıskançlık) yerilen bir davranıştır.'),
    Q('din', 'hz-muhammed', 'Hz. Muhammed\'in (s.a.v.) hayatıyla ilgili aşağıdaki olayların doğru sıralaması hangisidir?<br>I. Hicret<br>II. İlk vahiy<br>III. Doğumu<br>IV. Vefatı', ['III – II – I – IV', 'II – III – I – IV', 'III – I – II – IV', 'I – II – III – IV'], 0, 'Doğum (571) → İlk vahiy (610) → Hicret (622) → Vefat (632): <b>III – II – I – IV</b>'),
    Q('din', 'hz-muhammed', 'Hz. Muhammed\'i (s.a.v.) büyüten ve ona hayatı boyunca destek olan amcası kimdir?', ['Abdülmuttalip', 'Ebu Talip', 'Abdullah', 'Hz. Hamza'], 1, 'Dedesinin vefatından sonra onu amcası <b>Ebu Talip</b> büyütmüştür.'),
    Q('din', 'yorumlar', 'Aşağıdakilerden hangisi <b>itikadi</b> (inançla ilgili) mezheplerdendir?', ['Hanefilik', 'Malikilik', 'Eş\'arilik', 'Mevlevilik'], 2, '<b>Eş\'arilik</b> itikadi bir mezheptir. Hanefilik ve Malikilik fıkhi, Mevlevilik tasavvufi yorumdur.'),
    Q('din', 'yorumlar', P('Anadolu\'da yaşamış bu gönül insanı; sevgiyi, hoşgörüyü ve insanlara hizmeti öne çıkarmıştır. "Eline, beline, diline sahip ol." sözü onun öğütleri arasında yer alır.') + 'Metinde sözü edilen kişi kimdir?', ['Hacı Bektaş-ı Veli', 'İmam Maturidi', 'Ebu Hanife', 'İmam Şafii'], 0, '"Eline, beline, diline sahip ol." öğüdü <b>Hacı Bektaş-ı Veli</b>\'ye aittir.'),

    // ---- MATEMATİK ----
    Q('matematik', 'tam-sayilar', 'Deniz seviyesinin 24 m altında bulunan bir dalgıç önce 9 m daha aşağı iniyor, ardından 15 m yukarı çıkıyor.<br><br>Dalgıcın son durumda deniz seviyesine olan uzaklığı kaç metredir?', ['18', '30', '0', '48'], 0, '−24 − 9 + 15 = −18 → deniz seviyesine uzaklık <b>18 m</b>'),
    Q('matematik', 'tam-sayilar', '(−2)<sup>3</sup> · (−1)<sup>20</sup> − (−3)<sup>2</sup> işleminin sonucu kaçtır?', ['−17', '1', '−1', '17'], 0, '(−2)³ = −8, (−1)²⁰ = 1, (−3)² = 9<br>−8 · 1 − 9 = <b>−17</b>'),
    Q('matematik', 'rasyonel', F(3, 4) + ' ile ' + F(5, 6) + ' arasında bulunan rasyonel sayı aşağıdakilerden hangisidir?', [F(2, 3), F(4, 5), F(7, 8), F(5, 7)], 1, F(3, 4) + ' = 0,75 ve ' + F(5, 6) + ' ≈ 0,83. ' + F(4, 5) + ' = 0,8 bu iki sayı arasındadır.'),
    Q('matematik', 'rasyonel', 'Bir su deposunun ' + F(2, 3) + '\'ü doludur. Depodan 120 litre su kullanıldığında deponun ' + F(2, 5) + '\'i dolu kalıyor.<br><br>Bu deponun tamamı kaç litre su alır?', ['300', '360', '450', '600'], 2, 'Kullanılan kısım: ' + F(2, 3) + ' − ' + F(2, 5) + ' = ' + F(10, 15) + ' − ' + F(6, 15) + ' = ' + F(4, 15) + '<br>' + F(4, 15) + ' → 120 L ise ' + F(1, 15) + ' → 30 L. Tamamı: 15 · 30 = <b>450 L</b>'),
    Q('matematik', 'cebirsel', 'Bir sinema bileti x TL\'dir. Bir paket mısırın fiyatı, bilet fiyatının yarısından 10 TL azdır.<br><br>4 bilet ve 2 paket mısır alan bir ailenin ödediği tutarı gösteren cebirsel ifade hangisidir?', ['5x − 20', '5x − 10', '6x − 20', '4x + 20'], 0, 'Mısır: ' + F('x', 2) + ' − 10<br>4x + 2 · (' + F('x', 2) + ' − 10) = 4x + x − 20 = <b>5x − 20</b>'),
    Q('matematik', 'cebirsel', 'x = −3 ve y = 2 için 3x − 2y + x · y ifadesinin değeri kaçtır?', ['−19', '−7', '1', '−1'], 0, '3 · (−3) − 2 · 2 + (−3) · 2 = −9 − 4 − 6 = <b>−19</b>'),
    Q('matematik', 'denklem', 'Ardışık üç çift sayının toplamı 78\'dir.<br><br>Bu sayılardan en büyüğü kaçtır?', ['24', '26', '28', '30'], 2, 'x + (x + 2) + (x + 4) = 78 → 3x + 6 = 78 → x = 24. En büyük: <b>28</b>'),
    Q('matematik', 'denklem', '20 soruluk bir sınavda her doğru cevap 5 puan kazandırmakta, her yanlış cevap 2 puan kaybettirmektedir. Tüm soruları cevaplayan Selin 65 puan almıştır.<br><br>Selin kaç soruya doğru cevap vermiştir?', ['13', '14', '15', '16'], 2, 'Doğru: d, yanlış: 20 − d. 5d − 2(20 − d) = 65 → 7d − 40 = 65 → 7d = 105 → <b>d = 15</b>'),
    Q('matematik', 'oran-oranti', 'Bir kek tarifinde kullanılan unun şekere oranı ' + F(5, 2) + '\'dir. Bu tarifle hazırlanan bir kekte un ve şekerin toplam kütlesi 840 gramdır.<br><br>Bu kekte kaç gram un kullanılmıştır?', ['240', '420', '560', '600'], 3, 'Toplam 5 + 2 = 7 pay. Bir pay: 840 : 7 = 120 g<br>Un: 5 · 120 = <b>600 g</b>'),
    Q('matematik', 'oran-oranti', 'Saatte 90 km sabit hızla giden bir otomobil iki şehir arasındaki yolu 4 saatte almaktadır.<br><br>Aynı yolu saatte 120 km sabit hızla giden bir otomobil kaç saatte alır?', ['2,5', '3', '3,5', '5'], 1, 'Yol: 90 · 4 = 360 km. Hız artınca süre azalır (ters orantı): 360 : 120 = <b>3 saat</b>'),
    Q('matematik', 'yuzdeler', '40 kişilik bir sınıfta öğrencilerin %15\'i gözlük kullanmaktadır. Sınıfa gözlük kullanmayan 10 öğrenci daha katılıyor.<br><br>Son durumda sınıftaki gözlük kullanan öğrencilerin oranı yüzde kaçtır?', ['%10', '%12', '%15', '%20'], 1, 'Gözlüklü: 40 · 0,15 = 6. Yeni mevcut: 50<br>' + F(6, 50) + ' = ' + F(12, 100) + ' = <b>%12</b>'),
    Q('matematik', 'yuzdeler', 'Bir telefonun fiyatına art arda iki kez %10 zam yapılmıştır.<br><br>Telefonun fiyatı başlangıca göre toplam yüzde kaç artmıştır?', ['%20', '%21', '%11', '%22'], 1, '100 TL → %10 zam → 110 TL → %10 zam → 121 TL. Toplam artış <b>%21</b>'),
    Q('matematik', 'acilar', 'Kesişen iki doğrunun oluşturduğu komşu iki açının ölçüleri (2x + 10)° ve (3x − 5)°\'dir.<br><br>Buna göre x kaçtır?', ['25', '30', '35', '40'], 2, 'Komşu açılar bütünlerdir: 2x + 10 + 3x − 5 = 180 → 5x = 175 → <b>x = 35</b>'),
    Q('matematik', 'acilar', 'Bir açının tümlerinin ölçüsü, bütünlerinin ölçüsünün ' + F(1, 4) + '\'ü kadardır.<br><br>Bu açı kaç derecedir?', ['30', '45', '60', '75'], 2, '90 − x = ' + F('180 − x', 4) + ' → 360 − 4x = 180 − x → 3x = 180 → <b>x = 60°</b>'),
    Q('matematik', 'cokgenler', 'Bir üçgenin iç açılarının ölçüleri 2, 3 ve 4 sayıları ile doğru orantılıdır.<br><br>Bu üçgenin en büyük açısının ölçüsü kaç derecedir?', ['60', '70', '80', '90'], 2, '2k + 3k + 4k = 180 → 9k = 180 → k = 20. En büyük açı: 4 · 20 = <b>80°</b>'),
    Q('matematik', 'cokgenler', 'Köşegen uzunlukları 12 cm ve 16 cm olan bir eşkenar dörtgenin alanı kaç cm²\'dir?', ['96', '192', '56', '48'], 0, 'Alan = ' + F('12 · 16', 2) + ' = <b>96 cm²</b>'),
    Q('matematik', 'cember', 'Çapı 60 cm olan bir bisiklet tekerleği 1,8 km yol aldığında kaç tur atmış olur? (π = 3 alınız.)', ['100', '500', '1000', '3000'], 2, 'Bir tur = 3 · 60 = 180 cm. 1,8 km = 180 000 cm<br>180 000 : 180 = <b>1000</b> tur'),
    Q('matematik', 'cember', 'Yarıçapı 10 cm olan bir dairede merkez açısı 72° olan daire diliminin alanı kaç cm²\'dir? (π = 3 alınız.)', ['30', '60', '72', '120'], 1, 'Daire alanı: 3 · 100 = 300 cm². Dilim: 300 · ' + F(72, 360) + ' = 300 · ' + F(1, 5) + ' = <b>60 cm²</b>'),
    Q('matematik', 'veri', '12, 15, 15, 18 ve x sayılarından oluşan veri grubunun aritmetik ortalaması 16\'dır.<br><br>Bu veri grubunun ortancası ile tepe değerinin toplamı kaçtır?', ['30', '31', '33', '35'], 0, 'Toplam: 5 · 16 = 80 → x = 80 − 60 = 20<br>Sıralı: 12, 15, 15, 18, 20. Ortanca 15, tepe değer 15 → <b>30</b>'),
    Q('matematik', 'veri', 'Bir öğrencinin bir hafta boyunca kitap okumaya ayırdığı süreler (dakika) aşağıdaki grafikte verilmiştir.<br><br>Bu öğrenci kaç gün, haftalık ortalama sürenin <b>üzerinde</b> kitap okumuştur?', ['1', '2', '3', '4'], 1, 'Toplam: 30 + 45 + 20 + 50 + 35 = 180 dk, ortalama 180 : 5 = 36 dk.<br>36\'nın üzerinde: Salı (45) ve Perşembe (50) → <b>2</b> gün', sutun([['Pzt', 30], ['Salı', 45], ['Çar', 20], ['Per', 50], ['Cuma', 35]], 60, 10, 'Dakika'))
  ];

  return [
    { no: 1, baslik: 'LGS Tarzı Özel Deneme 1', sure: 120, sorular: d1 },
    { no: 2, baslik: 'LGS Tarzı Özel Deneme 2', sure: 120, sorular: d2 }
  ];
})();
